grid = [[6]*19 for _ in range(13)]
panels=[(1,7,1),(1,13,3),(7,7,7),(7,13,5)] # row, col, color
patterns={
1:[[0,0,1],[1,1,1],[0,0,1]],
3:[[1,1,0],[1,1,0],[1,0,0]],
7:[[0,1,1],[1,1,0],[0,0,1]],
5:[[0,1,1],[1,1,0],[0,1,1]],
}
for r,c,col in panels:
    for y in range(5):
        for x in range(5): grid[r+y][c+x]=col
    for y in range(3):
        for x in range(3):
            if patterns[col][y][x]==0: grid[r+1+y][c+1+x]=6
print('\n'.join(' '.join(map(str,row)) for row in grid))

